// Defaults are applied HERE. Real callers send "" for what they did not fill,
// so "" is the value every branch is built around, not an edge case.
def t = { v -> v == null ? '' : v.toString().trim() }
// Every parameter is read through hasVariable: an UNBOUND parameter is a MISSING
// Groovy variable, not a null one, and a direct reference dies with "No such
// property". That is what lets a data source with a smaller key set still call this.
def p = { String k -> binding.hasVariable(k) ? t(binding.getVariable(k)) : '' }

def act = p('action').toUpperCase()
if (act.isEmpty()) act = 'LIST'
def id  = p('payeeId')
def eid = p('employeeId')
def s   = p('search')
def lim = p('limit')
def off = p('offset')
def rawFilter = binding.hasVariable('filter') ? binding.getVariable('filter') : null

boolean valid = true
String reason = ''
def problems = []

if (!(act in ['LIST', 'CREATE', 'UPDATE'])) {
    problems << ('action must be LIST, CREATE or UPDATE, got: ' + act)
} else if (act == 'CREATE') {
    // employeeId is the object's unique key; firstName composes the required
    // nameField; currencyId and status are required by the schema.
    if (eid.isEmpty())                 problems << 'employeeId is required to create a person'
    if (p('firstName').isEmpty())      problems << 'firstName is required to create a person'
    if (p('currencyId').isEmpty())     problems << 'currencyId is required to create a person'
} else if (act == 'UPDATE' && id.isEmpty()) {
    problems << 'payeeId is required to update a person'
}

int pageLimit = 50
if (!lim.isEmpty()) {
    if (lim ==~ /^\d+$/) { pageLimit = Integer.parseInt(lim) } else { problems << ('limit must be a whole number, got: ' + lim) }
}
if (pageLimit < 1) pageLimit = 1
if (pageLimit > 200) pageLimit = 200

int pageOffset = 0
if (!off.isEmpty()) {
    if (off ==~ /^\d+$/) { pageOffset = Integer.parseInt(off) } else { problems << ('offset must be a whole number, got: ' + off) }
}

// ---- the draft record -------------------------------------------------------
// Coerced ONCE, here, so the guard node merges values rather than re-parsing
// strings.
//
// A blank STRING is '' and is PRESENT: on UPDATE that clears the field, which is
// what a user emptying the box means.
//
// A blank NUMBER or DATE is ABSENT from the map entirely, and on UPDATE that means
// LEAVE IT ALONE. There is no '' for a number, and a null cannot carry the
// intent either: the platform DROPS null-valued keys when it serialises between
// nodes (observed on tool 2026-09-10 - the draft arrived at the guard without its
// four null keys). So "clear this number" is not expressible here and is not
// pretended to be; clearing a terminationDate is a follow-up that needs a real
// sentinel, not a blank.
def draft = [:]
def provided = [] as Set
if (!p('employeeId').isEmpty()) provided << 'employeeId'
draft['employeeId'] = p('employeeId')
if (!p('firstName').isEmpty()) provided << 'firstName'
draft['firstName'] = p('firstName')
if (!p('lastName').isEmpty()) provided << 'lastName'
draft['lastName'] = p('lastName')
if (!p('email').isEmpty()) provided << 'email'
draft['email'] = p('email')
if (!p('userId').isEmpty()) provided << 'userId'
draft['userId'] = p('userId')
if (!p('currencyId').isEmpty()) provided << 'currencyId'
draft['currencyId'] = p('currencyId')
if (!p('personalCurrencyId').isEmpty()) provided << 'personalCurrencyId'
draft['personalCurrencyId'] = p('personalCurrencyId')
if (!p('hireDate').isEmpty()) { if (p('hireDate') ==~ /^\d+$/) { draft['hireDate'] = Long.parseLong(p('hireDate')); provided << 'hireDate' } else { problems << ('hireDate must be epoch millis, got: ' + p('hireDate')) } }
if (!p('terminationDate').isEmpty()) { if (p('terminationDate') ==~ /^\d+$/) { draft['terminationDate'] = Long.parseLong(p('terminationDate')); provided << 'terminationDate' } else { problems << ('terminationDate must be epoch millis, got: ' + p('terminationDate')) } }
if (!p('status').isEmpty()) provided << 'status'
draft['status'] = p('status')
if (!p('region').isEmpty()) provided << 'region'
draft['region'] = p('region')
if (!p('businessGroup').isEmpty()) provided << 'businessGroup'
draft['businessGroup'] = p('businessGroup')
if (!p('team').isEmpty()) provided << 'team'
draft['team'] = p('team')
if (!p('personalTarget').isEmpty()) { if (p('personalTarget') ==~ /^-?\d+(\.\d+)?$/) { draft['personalTarget'] = new BigDecimal(p('personalTarget')); provided << 'personalTarget' } else { problems << ('personalTarget must be a number, got: ' + p('personalTarget')) } }
if (!p('salary').isEmpty()) { if (p('salary') ==~ /^-?\d+(\.\d+)?$/) { draft['salary'] = new BigDecimal(p('salary')); provided << 'salary' } else { problems << ('salary must be a number, got: ' + p('salary')) } }

// ---- the filter block -------------------------------------------------------
// The screen sends the platform's own wire shape - {op, values:[{field, op, values}]},
// groups nested by the same rule - and the storage node speaks a DIFFERENT dialect:
// {operator, filters:[{property, filter:{operator, value}}]}. Translating between the
// two is this section's whole job. Sending the wire shape straight through answers
// HTTP 500 "Filter$Op ... op is null" at RUN time, which names no node.
//
// Only the operators the screen can offer are accepted (platform-filter.ts,
// TEXT_OPERATORS). Every one takes exactly one value or none, which is why there is
// no list-valued case: dates and money are NOT filterable here, deliberately, and
// adding one means growing a two-value BETWEEN branch FIRST.
def FILTER_FIELDS = ["employeeId","firstName","lastName","name","email","status","region","businessGroup","team"] as Set
def ONE_VALUE_OPS = ['EQUAL', 'NOT_EQUAL', 'ICONTAINS', 'NOT_ICONTAINS', 'CONTAINS', 'NOT_CONTAINS',
                     'STARTS_WITH', 'NOT_STARTS_WITH', 'ENDS_WITH', 'NOT_ENDS_WITH', 'REGEX', 'NOT_REGEX'] as Set
def NO_VALUE_OPS = ['EXISTS', 'MISSING'] as Set
def GROUP_OPS = ['AND', 'OR'] as Set

def parsed = rawFilter
if (parsed instanceof String) {
    def raw = parsed.trim()
    if (raw.isEmpty()) parsed = null
    else {
        try { parsed = new groovy.json.JsonSlurper().parseText(raw) }
        catch (Exception e) { problems << ('filter is not valid JSON: ' + e.getMessage()); parsed = null }
    }
}
if (parsed instanceof Map && parsed.isEmpty()) parsed = null

def toStorage
toStorage = { node, String path ->
    if (!(node instanceof Map)) { problems << (path + ': a filter node must be an object'); return null }
    def op = (node.op == null) ? '' : String.valueOf(node.op).trim().toUpperCase()
    def field = (node.field == null) ? '' : String.valueOf(node.field).trim()

    // No field means a GROUP. The wire shape carries a group's children in `values`, the
    // same key a leaf uses for its operands - the presence of `field` is the only thing
    // that tells them apart.
    if (field.isEmpty()) {
        if (!GROUP_OPS.contains(op)) { problems << (path + ': a group needs op AND or OR, got "' + op + '"'); return null }
        def kids = []
        def vals = node.values
        if (vals != null && !(vals instanceof List)) { problems << (path + ': values of a group must be a list'); return null }
        (vals ?: []).eachWithIndex { child, i ->
            def c = toStorage(child, path + '.values[' + i + ']')
            if (c != null) kids << c
        }
        // An empty group is not an error - it is a filter the user started and did not
        // finish. Dropping it means "no filter", which is what the screen shows anyway.
        if (kids.isEmpty()) return null
        return [operator: op, filters: kids]
    }

    if (!FILTER_FIELDS.contains(field)) { problems << (path + ': unknown or non-filterable field "' + field + '"'); return null }
    boolean takesValue = ONE_VALUE_OPS.contains(op)
    if (!takesValue && !NO_VALUE_OPS.contains(op)) { problems << (path + ': operator "' + op + '" is not supported for ' + field); return null }

    def leaf = [operator: op]
    if (takesValue) {
        def vals = (node.values instanceof List) ? node.values : (node.values == null ? [] : [node.values])
        def first = vals.findResult { (it == null) ? null : (String.valueOf(it).trim() ?: null) }
        if (first == null) { problems << (path + ': ' + op + ' needs one value'); return null }
        if (op == 'REGEX' || op == 'NOT_REGEX') {
            try { java.util.regex.Pattern.compile(first) }
            catch (Exception e) { problems << (path + ': not a valid regular expression: ' + first); return null }
        }
        leaf.value = first
    }
    return [property: 'properties.' + field, filter: leaf]
}

def filterNode = (parsed == null) ? null : toStorage(parsed, 'filter')

// Collected, not thrown at the first one: a caller fixing three mistakes one
// refusal at a time is the experience this avoids.
if (!problems.isEmpty()) { valid = false; reason = problems.join('; ') }

def lf = []
if (!valid) {
    lf << [property: 'id', filter: [operator: 'EQUAL', value: '__invalid_input__']]
} else {
    // Search and filter are ANDed: the box narrows whatever the block already selected.
    if (!s.isEmpty()) {
        lf << [operator: 'OR', filters: [
            [property: 'properties.employeeId', filter: [operator: 'ICONTAINS', value: s]],
            [property: 'properties.name',       filter: [operator: 'ICONTAINS', value: s]],
            [property: 'properties.email',      filter: [operator: 'ICONTAINS', value: s]]]]
    }
    if (filterNode != null) lf << filterNode
}

// The unique-key pre-check. A unique hit at WRITE time is a raw Mongo E11000
// that kills the run - it is never save-time visible, so it is checked first.
def df = (valid && act != 'LIST' && !eid.isEmpty())
    ? [[property: 'properties.employeeId', filter: [operator: 'EQUAL', value: eid]]]
    : [[property: 'id', filter: [operator: 'EQUAL', value: '__none__']]]

// The UPDATE target, read back so a missing id is NOT_FOUND rather than an engine error.
def of = (valid && act == 'UPDATE')
    ? [[property: 'id', filter: [operator: 'EQUAL', value: id]]]
    : [[property: 'id', filter: [operator: 'EQUAL', value: '__none__']]]

return [valid: valid, reason: reason, action: act, payeeId: id, employeeId: eid,
        pageLimit: pageLimit, pageOffset: pageOffset,
        draft: draft, provided: (provided as List),
        listFilter: [operator: 'AND', filters: lf],
        dupFilter:  [operator: 'AND', filters: df],
        oneFilter:  [operator: 'AND', filters: of]]

def t = { v -> v == null ? '' : v.toString().trim() }
def act = t(norm.action)
def id  = t(norm.payeeId)
def eid = t(norm.employeeId)
def draft = (norm.draft == null) ? [:] : norm.draft
def provided = ((norm.provided == null) ? [] : norm.provided) as Set

// DUPLICATE: any OTHER record already carries this employeeId. On UPDATE the
// record's own row is not a clash with itself.
boolean isDup = false
if (dupRows != null) dupRows.each { r -> if (String.valueOf(r.id) != id) isDup = true }

// NOT_FOUND: an UPDATE whose target no longer exists.
boolean notFound = (act == 'UPDATE') && (oneRows == null || oneRows.isEmpty())

def cur = (oneRows != null && !oneRows.isEmpty() && oneRows[0].properties != null) ? oneRows[0].properties : [:]
def curV = { k -> cur[k] == null ? '' : cur[k].toString() }

def REQUIRED = ["employeeId","firstName","currencyId","status"] as Set

// On UPDATE the caller is a form that posts every field, so an OPTIONAL field
// arriving blank means "clear it" - '' for a string, null for a number or date.
// The REQUIRED fields fall back to what is already stored, so a partial payload
// can never blank out the unique key or the required currency.
def rec = [:]
draft.each { k, v ->
    if (act == 'CREATE') { rec[k] = v }
    else if (REQUIRED.contains(k) && !provided.contains(k)) { rec[k] = curV(k) }
    else { rec[k] = v }
}

// ---- the composed name, and the BACKFILL guard ------------------------------
// `name` is the object's required nameField and is never an input: the screen
// collects First and Last, and two writers for one field is how a display name
// drifts from the boxes that produce it.
def fn = t(rec.firstName)
def ln = t(rec.lastName)
if (act == 'UPDATE' && fn.isEmpty() && ln.isEmpty()) {
    def sf = curV('firstName'), sl = curV('lastName'), sn = curV('name')
    if (sf.isEmpty() && sl.isEmpty() && !sn.isEmpty()) {
        // BACKFILL: a record written before firstName/lastName existed. Split the
        // stored name once, rather than composing '' and blanking someone's name.
        int sp = sn.indexOf(' ')
        fn = (sp < 0) ? sn : sn.substring(0, sp)
        ln = (sp < 0) ? '' : sn.substring(sp + 1).trim()
    } else { fn = sf; ln = sl }
    rec.firstName = fn
    rec.lastName = ln
}
def composed = [fn, ln].findAll { it }.join(' ')
// Last ditch: the nameField is required, so it is never written empty.
rec.name = composed.isEmpty() ? curV('name') : composed

// status has a schema default only in the sense that the object requires it.
// ACTIVE, uppercase - that is what the 21 rows on tool actually carry, checked
// 2026-09-10. A mixed-case status would sort and filter as a second value.
if (t(rec.status).isEmpty()) rec.status = (act == 'CREATE') ? 'ACTIVE' : curV('status')

return [isDup: isDup, notFound: notFound, record: rec,
        dupMessage: 'A person with employee id "' + eid + '" already exists.',
        nfMessage: 'No person with id "' + id + '" exists.']
